1	import { toBlob } from "html-to-image";
2	
3	const WINDOW_HORIZONTAL_MARGIN = 32;
4	const PREVIEW_HORIZONTAL_PADDING_IN_DIALOG = 40;
5	const PREVIEW_WIDTH_BOOST_IN_DIALOG = 48;
6	
7	export const MEMO_SHARE_IMAGE_CONFIG = {
8	  dialogExtraWidth: 80,
9	  maxWidth: 520,
10	  minWidth: 260,
11	  previewScale: 0.9,
12	  viewportMargin: 48,
13	} as const;
14	
15	const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
16	
17	const isExportableImageUrl = (value?: string) => {
18	  if (!value) {
19	    return false;
20	  }
21	
22	  if (value.startsWith("/") || value.startsWith("data:") || value.startsWith("blob:")) {
23	    return true;
24	  }
25	
26	  try {
27	    return new URL(value, window.location.origin).origin === window.location.origin;
28	  } catch {
29	    return false;
30	  }
31	};
32	
33	const waitForPreviewAssets = async (node: HTMLElement) => {
34	  try {
35	    await document.fonts?.ready;
36	  } catch {
37	    // Ignore font loading failures and continue with the best available render.
38	  }
39	
40	  const images = Array.from(node.querySelectorAll("img"));
41	  await Promise.all(
42	    images.map(
43	      (image) =>
44	        new Promise<void>((resolve) => {
45	          if (image.complete) {
46	            resolve();
47	            return;
48	          }
49	
50	          image.addEventListener("load", () => resolve(), { once: true });
51	          image.addEventListener("error", () => resolve(), { once: true });
52	        }),
53	    ),
54	  );
55	};
56	
57	export const buildMemoShareImageFileName = (memoName: string) => {
58	  const suffix = memoName.split("/").pop() || "memo";
59	  return `memo-${suffix}.png`;
60	};
61	
62	export const getMemoSharePreviewWidth = (cardWidth: number) => {
63	  const viewportWidth =
64	    typeof window === "undefined" ? MEMO_SHARE_IMAGE_CONFIG.maxWidth : window.innerWidth - MEMO_SHARE_IMAGE_CONFIG.viewportMargin;
65	  const baseWidth = cardWidth || viewportWidth;
66	
67	  return clamp(
68	    Math.round(baseWidth * MEMO_SHARE_IMAGE_CONFIG.previewScale),
69	    MEMO_SHARE_IMAGE_CONFIG.minWidth,
70	    MEMO_SHARE_IMAGE_CONFIG.maxWidth,
71	  );
72	};
73	
74	export const getMemoShareDialogWidth = (previewWidth: number) => {
75	  const viewportWidth =
76	    typeof window === "undefined" ? previewWidth + MEMO_SHARE_IMAGE_CONFIG.dialogExtraWidth : window.innerWidth - WINDOW_HORIZONTAL_MARGIN;
77	  return Math.min(previewWidth + MEMO_SHARE_IMAGE_CONFIG.dialogExtraWidth, viewportWidth);
78	};
79	
80	export const getMemoShareRenderWidth = (previewWidth: number, dialogWidth: number) => {
81	  const maxRenderWidth = Math.max(MEMO_SHARE_IMAGE_CONFIG.minWidth, dialogWidth - PREVIEW_HORIZONTAL_PADDING_IN_DIALOG);
82	  return clamp(previewWidth + PREVIEW_WIDTH_BOOST_IN_DIALOG, MEMO_SHARE_IMAGE_CONFIG.minWidth, maxRenderWidth);
83	};
84	
85	export const getMemoSharePreviewAvatarUrl = (avatarUrl?: string) => (isExportableImageUrl(avatarUrl) ? avatarUrl : undefined);
86	
87	export const createMemoShareImageBlob = async (node: HTMLElement) => {
88	  await waitForPreviewAssets(node);
89	
90	  const rect = node.getBoundingClientRect();
91	  const width = Math.ceil(rect.width || node.offsetWidth || node.clientWidth);
92	  const height = Math.ceil(rect.height || node.offsetHeight || node.clientHeight);
93	
94	  const blob = await toBlob(node, {
95	    cacheBust: true,
96	    height,
97	    pixelRatio: Math.max(2, Math.min(window.devicePixelRatio || 1, 3)),
98	    width,
99	    filter: (currentNode) => {
100	      if (!(currentNode instanceof HTMLElement)) {
101	        return true;
102	      }
103	
104	      if (currentNode instanceof HTMLImageElement) {
105	        return isExportableImageUrl(currentNode.currentSrc || currentNode.src);
106	      }
107	
108	      return !(currentNode instanceof HTMLVideoElement);
109	    },
110	  });
111	
112	  if (!blob) {
113	    throw new Error("Failed to render image");
114	  }
115	
116	  return blob;
117	};
